<?php

declare(strict_types=1);

namespace App\Play\Domain\Campaign\Lists;

/**
 * The campaign already holds a Place with this id. Ids are generated by the caller, so a repeated
 * command must not replace the existing Place.
 */
final class PlaceAlreadyExists extends \DomainException
{
    public static function withId(PlaceId $id): self
    {
        return new self(\sprintf('Place "%s" already exists.', $id->toString()));
    }
}
